const crypto = require('crypto');

const EXPECTED_REPO = 'docrod29-ai/agenda-medica';
const webhookSecret = $env.AUSCULTA_GITHUB_WEBHOOK_SECRET;
const githubToken = $env.AUSCULTA_GITHUB_TOKEN;

if (!webhookSecret || !githubToken) {
  throw new Error('Missing AUSCULTA_GITHUB_WEBHOOK_SECRET or AUSCULTA_GITHUB_TOKEN');
}

const input = $input.first();
const headers = input.json.headers || {};
const event = headers['x-github-event'];
const delivery = headers['x-github-delivery'];
const signature = headers['x-hub-signature-256'];

if (!event || !delivery || !signature) throw new Error('Missing required GitHub webhook headers');

const encoded = input.binary?.data?.data;
if (!encoded) throw new Error('Raw webhook body is required');

const rawBody = Buffer.from(encoded, 'base64');
const expectedSignature = 'sha256=' + crypto.createHmac('sha256', webhookSecret).update(rawBody).digest('hex');
const supplied = Buffer.from(signature);
const expected = Buffer.from(expectedSignature);
if (supplied.length !== expected.length || !crypto.timingSafeEqual(supplied, expected)) {
  throw new Error('Invalid GitHub webhook signature');
}

const payload = JSON.parse(rawBody.toString('utf8'));
if (payload.repository?.full_name !== EXPECTED_REPO) {
  return [{ json: { ignored: true, reason: 'foreign_repository', event, delivery } }];
}

const api = 'https://api.github.com';
const commonHeaders = {
  Authorization: `Bearer ${githubToken}`,
  Accept: 'application/vnd.github+json',
  'X-GitHub-Api-Version': '2022-11-28',
  'User-Agent': 'ausculta-n8n-dev-autopilot-v1',
};

async function gh(path, options = {}) {
  const response = await fetch(`${api}${path}`, {
    ...options,
    headers: { ...commonHeaders, ...(options.headers || {}) },
  });
  if (!response.ok) {
    const body = await response.text();
    throw new Error(`GitHub ${response.status} ${path}: ${body.slice(0, 1000)}`);
  }
  if (response.status === 204) return null;
  const text = await response.text();
  return text ? JSON.parse(text) : null;
}

async function getPr(prNumber) {
  return gh(`/repos/${EXPECTED_REPO}/pulls/${prNumber}`);
}
async function getRecentComments(prNumber) {
  return gh(`/repos/${EXPECTED_REPO}/issues/${prNumber}/comments?per_page=100&sort=created&direction=desc`);
}
async function addComment(prNumber, body) {
  return gh(`/repos/${EXPECTED_REPO}/issues/${prNumber}/comments`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ body }),
  });
}
async function exactCommandExists(prNumber, command) {
  const comments = await getRecentComments(prNumber);
  return comments.some((c) => (c.body || '').trim() === command);
}
function validProductPr(pr, expectedSha) {
  return Boolean(
    pr &&
    pr.state === 'open' &&
    pr.head?.repo?.full_name === EXPECTED_REPO &&
    typeof pr.head?.ref === 'string' &&
    pr.head.ref.startsWith('product/') &&
    pr.head.sha === expectedSha
  );
}

if (event === 'workflow_run' && payload.action === 'completed') {
  const run = payload.workflow_run || {};
  const prs = Array.isArray(run.pull_requests) ? run.pull_requests : [];
  const prNumber = prs[0]?.number;

  if (run.name === 'CI' && prNumber && run.head_sha) {
    const pr = await getPr(prNumber);
    if (!validProductPr(pr, run.head_sha)) {
      return [{ json: { ignored: true, reason: 'stale_or_nonproduct_ci', event, delivery, prNumber, sha: run.head_sha } }];
    }

    if (run.conclusion === 'success') {
      const command = `/ausculta-codex-judge ${run.head_sha}`;
      if (!(await exactCommandExists(prNumber, command))) {
        await addComment(prNumber, command);
        return [{ json: { action: 'codex_triggered', prNumber, sha: run.head_sha, delivery } }];
      }
      return [{ json: { ignored: true, reason: 'codex_already_triggered', prNumber, sha: run.head_sha, delivery } }];
    }

    if (['failure', 'cancelled', 'timed_out'].includes(run.conclusion) && (run.run_attempt || 1) < 2) {
      await gh(`/repos/${EXPECTED_REPO}/actions/runs/${run.id}/rerun-failed-jobs`, { method: 'POST' });
      return [{ json: { action: 'ci_rerun_once', prNumber, sha: run.head_sha, runId: run.id, delivery } }];
    }

    return [{ json: { action: 'external_recovery_required', prNumber, sha: run.head_sha, conclusion: run.conclusion, runId: run.id, delivery } }];
  }

  if (run.name === 'Ausculta Product Claude Comment Writer' && run.conclusion !== 'success') {
    return [{ json: { action: 'writer_failed', sha: run.head_sha, conclusion: run.conclusion, runId: run.id, htmlUrl: run.html_url, delivery } }];
  }

  return [{ json: { ignored: true, reason: 'workflow_not_in_v1_scope', workflow: run.name, conclusion: run.conclusion, delivery } }];
}

if (event === 'issue_comment' && payload.action === 'created' && payload.issue?.pull_request) {
  const comment = payload.comment || {};
  const prNumber = payload.issue.number;
  const body = String(comment.body || '');

  if (comment.user?.login !== 'github-actions[bot]') {
    return [{ json: { ignored: true, reason: 'untrusted_comment_actor', prNumber, delivery } }];
  }

  const verdictMatch = body.match(/\{[\s\S]*"verdict"\s*:\s*"(PASS|FAIL)"[\s\S]*\}/);
  if (!verdictMatch) {
    return [{ json: { ignored: true, reason: 'not_a_verdict_comment', prNumber, delivery } }];
  }

  let verdict;
  try { verdict = JSON.parse(verdictMatch[0]); }
  catch { return [{ json: { ignored: true, reason: 'verdict_json_parse_failed', prNumber, delivery } }]; }

  const auditedSha = verdict.audited_sha;
  if (!/^[0-9a-f]{40}$/.test(auditedSha || '') || verdict.independent !== true || verdict.read_only !== true) {
    return [{ json: { ignored: true, reason: 'invalid_verdict_contract', prNumber, delivery } }];
  }

  const pr = await getPr(prNumber);
  if (!validProductPr(pr, auditedSha)) {
    return [{ json: { ignored: true, reason: 'stale_verdict', prNumber, auditedSha, currentSha: pr.head?.sha, delivery } }];
  }

  const blockers = Array.isArray(verdict.findings)
    ? verdict.findings.filter((f) => f?.blocking === true && ['P0', 'P1'].includes(f?.severity))
    : [];

  if (verdict.verdict === 'PASS' || blockers.length === 0) {
    return [{ json: { action: 'gate_passed', prNumber, sha: auditedSha, verdict: verdict.verdict, blockers: blockers.length, delivery } }];
  }

  const command = `/ausculta-claude-writer ${auditedSha}`;
  if (!(await exactCommandExists(prNumber, command))) {
    await addComment(prNumber, command);
    return [{ json: { action: 'claude_repair_triggered', prNumber, sha: auditedSha, blockers: blockers.length, delivery } }];
  }

  return [{ json: { ignored: true, reason: 'claude_already_triggered_for_sha', prNumber, sha: auditedSha, blockers: blockers.length, delivery } }];
}

return [{ json: { ignored: true, reason: 'event_not_in_v1_scope', event, delivery } }];
